                        Files.writeString(evidence.resolve("foreign-generation-evidence.txt"),
                                "plan=" + gate.planTripleId + " beforeBegin=" + gate.beforeBeginId
                                        + " childBefore=" + gate.foreignBeforeId + " childAfter=" + gate.foreignAfterId
                                        + " current=" + current + "\n", java.nio.file.StandardOpenOption.CREATE_NEW);
                        assertTrue(gate.planTripleId >= 0L, "the paired scan must record its actual triple generation");
                        assertEquals(gate.planTripleId, gate.beforeBeginId, "the plan must still match at pre-begin");
                        assertEquals(gate.beforeBeginId, gate.foreignBeforeId, "the child must start from that generation");
                        assertEquals(Math.addExact(gate.foreignBeforeId, 1L), gate.foreignAfterId,
                                "the child must commit exactly one later native generation");
                        assertEquals(gate.foreignAfterId, current, "the foreign generation must be current before release");
